/bin/zsh -c "python -c 'import itertools
for n in range(4,10):
 for seq in itertools.combinations_with_replacement(range(1,10),n):
  seq=seq[::-1]; a=[]; b=[]; pa=[]; pb=[]
  for w in seq:
   for i,v in enumerate(a):
    if v+w<=10: a[i]+=w; pa[i].append(w); break
   else: a.append(w); pa.append([w])
   candidates=[i for i,v in enumerate(b) if v+w<=10]
   if candidates: i=max(candidates,key=lambda i:b[i]); b[i]+=w; pb[i].append(w)
   else: b.append(w); pb.append([w])
  if pa"'!=pb:
   print(seq,pa,pb); raise SystemExit'"'"

